// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

import "../interfaces/IATMAccessControl.sol";

/// @dev The File contract every ATM contract reads its addresses from.
interface IACLFile {
    function accessControl() external view returns (address);
}

/// @title ATMAccessControlDAO v1.0.0
/// @notice User approval DAO for ATMAccessControl. Holds only pending requests; every state
///         change goes through an ACL hook that re-checks the ACL invariants, so a bug here can
///         only do what is already valid in the ACL.
///         Proposals with one approver (listed per approver for the front end):
///         1. PROTECTION: a frozen wallet asks; only its own safe wallet approves -> PROTECTED.
///         2. MOVE_UP: a FROZEN or PROTECTED wallet W whose safe wallet S1 is restricted moves to
///            S1's own safe wallet S2 (payouts then go to S2). Only possible while W -> S1 -> S2
///            are linked. Either side starts it: W asks and S2 approves, or S2 asks and W approves.
///         Every proposal has a global id. Each approver has a pending list and counters, and
///         approves / rejects by id. A wallet has at most one open proposal per kind; asking again
///         replaces the old one.
///         Verifiers: holders of the ACL custom type set with setVerifierType (not frozen /
///         blacklisted). Verifier vote: a PROTECTED wallet proposes a new safe wallet, verifiers
///         approve (threshold >= 3). Off by default; the owner turns it on with setVerifierVoteEnabled.
///         Custom-type flows: per custom type the owner sets who may ask (the wallet itself and/or
///         a verifier) and who approves (verifier vote with a threshold, or the wallet's safe
///         wallet). Off for every type until configured; the ACL must also open the type
///         (ACL.setTypeDaoAllowed).
/// @dev Pause: any ACL operator or the owner can pause; only the owner unpauses. Cancels work
///      while paused.
///      The ACL is found through File.accessControl() on every call, like the Factory and the
///      Trader, so it follows File if the ACL ever moves (the new ACL must then setDao(this)).
contract ATMAccessControlDAO {
    uint256 public constant MIN_VERIFIER_THRESHOLD = 3;
    /// @dev ACL custom type ids start here (1-4 are built-ins)
    uint256 internal constant FIRST_CUSTOM_TYPE = 5;

    bool private _initialized;
    address public owner;
    address public pendingOwner;
    /// @notice File proxy; the ACL is File.accessControl().
    address public file;
    bool public paused;
    /// @dev stored value; effective threshold is never below MIN_VERIFIER_THRESHOLD
    uint256 private _verifierThreshold;

    uint8 public constant KIND_PROTECTION = 0;
    uint8 public constant KIND_MOVE_UP = 1;
    uint8 public constant STATUS_PENDING = 1;
    uint8 public constant STATUS_APPROVED = 2;
    uint8 public constant STATUS_CANCELLED = 3; // cancelled by the wallet / owner, or replaced
    uint8 public constant STATUS_REJECTED = 4; // rejected by the safe wallet

    /// @notice A request with one approver (see approverOf).
    struct Proposal {
        address wallet; // the wallet whose safe wallet / status changes
        uint8 kind;
        uint8 status;
        uint64 createdAt;
        bool bySafe; // MOVE_UP only: S2 asked, so the wallet approves
        address safeWallet; // PROTECTION: wallet's safe wallet · MOVE_UP: the new safe wallet S2
        address fromSafe; // MOVE_UP: the restricted safe wallet S1; PROTECTION: zero
    }

    struct SafeWalletRequest {
        address newSafeWallet;
        address currentSafeWallet; // safe wallet at request time
        uint256 approvals;
        uint256 threshold; // snapshot
        uint256 nonce;
        bool active;
    }

    mapping(address => SafeWalletRequest) public safeWalletRequests; // by protected wallet
    mapping(address => mapping(uint256 => mapping(address => bool))) private _approvals;

    /// @notice Number of proposals ever created; ids are 1..proposalCount.
    uint256 public proposalCount;
    mapping(uint256 => Proposal) private _proposals;
    /// @notice Open proposal id of a wallet per kind (0 = none).
    mapping(address => mapping(uint8 => uint256)) public openProposalOf;
    /// @dev every proposal ever addressed to an approver (history)
    mapping(address => uint256[]) private _safeProposalIds;
    /// @dev pending proposals of an approver (swap-and-pop set)
    mapping(address => uint256[]) private _pendingIds;
    mapping(uint256 => uint256) private _pendingPos; // id -> index + 1 in _pendingIds[approver]
    /// @notice Verifier vote switch (off at deployment).
    bool public verifierVoteEnabled;

    // --- custom-type flows (appended; do not reorder the storage above) ---

    /// @dev TypeFlow.requestBy bits
    uint8 public constant REQUEST_BY_WALLET = 1; // the wallet asks for itself
    uint8 public constant REQUEST_BY_VERIFIER = 2; // an active verifier asks for a wallet
    /// @dev TypeFlow.approveBy
    uint8 public constant APPROVE_BY_VERIFIERS = 1; // `threshold` active verifiers
    uint8 public constant APPROVE_BY_SAFE_WALLET = 2; // the wallet's safe wallet

    /// @notice requestBy = 0 means the flow is off for that type.
    struct TypeFlow {
        uint8 requestBy;
        uint8 approveBy;
        uint16 threshold; // APPROVE_BY_VERIFIERS only, >= 1
        bool allowAdd;
        bool allowRemove;
    }

    struct TypeRequest {
        address wallet;
        uint256 typeId;
        bool add; // true = join the type, false = leave it
        uint8 status; // STATUS_*
        uint8 approveBy; // snapshot of the flow at request time
        uint16 threshold; // snapshot (verifier mode)
        uint16 approvals; // verifier mode
        uint64 createdAt;
        address requester;
        address approver; // safe-wallet mode: the safe wallet at request time
    }

    mapping(uint256 => TypeFlow) private _typeFlows;
    /// @notice Number of type requests ever created; ids are 1..typeRequestCount.
    uint256 public typeRequestCount;
    mapping(uint256 => TypeRequest) private _typeRequests;
    mapping(uint256 => mapping(address => bool)) private _typeApprovals;
    /// @notice Open type request of a wallet per type (0 = none). Asking again replaces it.
    mapping(address => mapping(uint256 => uint256)) public openTypeRequestOf;
    /// @notice The ACL custom type whose holders are the verifiers (0 = no verifiers).
    uint256 public verifierTypeId;

    event OwnershipTransferInitiated(address indexed currentOwner, address indexed pendingOwner);
    event OwnershipTransferred(address indexed previousOwner, address indexed newOwner);
    event PausedSet(bool paused, address indexed by);
    event VerifierThresholdSet(uint256 threshold);
    event VerifierVoteEnabledSet(bool enabled);
    event ProposalCreated(
        uint256 indexed id,
        uint8 kind,
        address indexed wallet,
        address indexed safeWallet,
        address fromSafe
    );
    event ProposalApproved(uint256 indexed id, uint8 kind, address indexed wallet, address indexed safeWallet);
    event ProposalClosed(uint256 indexed id, uint8 status, address indexed by);
    event SafeWalletProposed(address indexed wallet, address indexed newSafeWallet, uint256 nonce, uint256 threshold);
    event SafeWalletRequestApproved(address indexed wallet, uint256 nonce, address indexed verifier, uint256 approvals);
    event SafeWalletRequestExecuted(address indexed wallet, address indexed newSafeWallet, uint256 nonce);
    event SafeWalletRequestCancelled(address indexed wallet, uint256 nonce, address indexed by);
    event VerifierTypeSet(uint256 indexed typeId);
    event TypeFlowSet(uint256 indexed typeId, uint8 requestBy, uint8 approveBy, uint16 threshold, bool allowAdd, bool allowRemove);
    event TypeRequestCreated(
        uint256 indexed id,
        address indexed wallet,
        uint256 indexed typeId,
        bool add,
        address requester,
        address approver,
        uint16 threshold
    );
    event TypeRequestApproved(uint256 indexed id, address indexed by, uint16 approvals);
    event TypeRequestExecuted(uint256 indexed id, address indexed wallet, uint256 indexed typeId, bool add);
    event TypeRequestClosed(uint256 indexed id, uint8 status, address indexed by);

    modifier onlyOwner() {
        require(msg.sender == owner, "ACLDAO: not owner");
        _;
    }

    modifier whenNotPaused() {
        require(!paused, "ACLDAO: paused");
        _;
    }

    constructor() {
        _initialized = true; // implementation cannot be initialized
    }

    function initialize(address _file, address _owner) external {
        require(!_initialized, "ACLDAO: already initialized");
        require(_file != address(0) && _owner != address(0), "ACLDAO: zero address");
        _initialized = true;
        file = _file;
        owner = _owner;
        emit OwnershipTransferred(address(0), _owner);
    }

    /// @notice The ACL this DAO works with: File.accessControl().
    function acl() public view returns (IATMAccessControl) {
        address ac = IACLFile(file).accessControl();
        require(ac != address(0), "ACLDAO: accessControl not set");
        return IATMAccessControl(ac);
    }

    // ---------------------------------------------------------------------
    // Admin
    // ---------------------------------------------------------------------

    function transferOwnership(address newOwner) external onlyOwner {
        require(newOwner != address(0), "ACLDAO: zero address");
        pendingOwner = newOwner;
        emit OwnershipTransferInitiated(owner, newOwner);
    }

    function acceptOwnership() external {
        require(msg.sender == pendingOwner, "ACLDAO: not pending owner");
        emit OwnershipTransferred(owner, pendingOwner);
        owner = pendingOwner;
        pendingOwner = address(0);
    }

    function pause() external {
        require(msg.sender == owner || acl().operators(msg.sender), "ACLDAO: not operator");
        paused = true;
        emit PausedSet(true, msg.sender);
    }

    function unpause() external onlyOwner {
        paused = false;
        emit PausedSet(false, msg.sender);
    }

    function verifierThreshold() public view returns (uint256) {
        return _verifierThreshold < MIN_VERIFIER_THRESHOLD ? MIN_VERIFIER_THRESHOLD : _verifierThreshold;
    }

    /// @notice Turns the verifier vote (proposeSafeWallet / approveSafeWallet) on or off.
    function setVerifierVoteEnabled(bool enabled) external onlyOwner {
        verifierVoteEnabled = enabled;
        emit VerifierVoteEnabledSet(enabled);
    }

    function setVerifierThreshold(uint256 threshold) external onlyOwner {
        require(threshold >= MIN_VERIFIER_THRESHOLD, "ACLDAO: threshold below minimum");
        _verifierThreshold = threshold;
        emit VerifierThresholdSet(threshold);
    }

    /// @notice Chooses the ACL custom type whose holders vote as verifiers (0 = nobody).
    ///         A verifier counts while it holds the type (not expired) and is not frozen / blacklisted.
    function setVerifierType(uint256 typeId) external onlyOwner {
        if (typeId != 0) _requireCustomType(typeId);
        verifierTypeId = typeId;
        emit VerifierTypeSet(typeId);
    }

    /// @notice Who may ask and who approves for a custom type. requestBy = 0 turns the flow off
    ///         (open requests can then no longer be approved). The ACL must also open the type
    ///         with setTypeDaoAllowed.
    function setTypeFlow(uint256 typeId, TypeFlow calldata flow) external onlyOwner {
        if (flow.requestBy != 0) {
            require(flow.requestBy <= (REQUEST_BY_WALLET | REQUEST_BY_VERIFIER), "ACLDAO: bad requestBy");
            require(
                flow.approveBy == APPROVE_BY_SAFE_WALLET || (flow.approveBy == APPROVE_BY_VERIFIERS && flow.threshold > 0),
                "ACLDAO: bad approveBy"
            );
            require(flow.allowAdd || flow.allowRemove, "ACLDAO: nothing allowed");
            _requireCustomType(typeId);
        }
        _typeFlows[typeId] = flow;
        emit TypeFlowSet(typeId, flow.requestBy, flow.approveBy, flow.threshold, flow.allowAdd, flow.allowRemove);
    }

    // ---------------------------------------------------------------------
    // Safe-wallet proposals: requests
    // ---------------------------------------------------------------------

    /// @notice Called by the frozen wallet itself. Goes to its own safe wallet for approval.
    function requestProtection() external whenNotPaused returns (uint256 id) {
        address safe = _checkProtectable(msg.sender);
        id = _open(KIND_PROTECTION, msg.sender, safe, address(0), false);
    }

    /// @notice Called by a FROZEN or PROTECTED wallet whose safe wallet S1 is restricted. Goes to
    ///         S1's own safe wallet S2 for approval.
    function requestMoveToSafeOfSafe() external whenNotPaused returns (uint256 id) {
        (address s1, address s2) = _moveTargets(msg.sender);
        id = _open(KIND_MOVE_UP, msg.sender, s2, s1, false);
    }

    /// @notice Called by S2 (the safe wallet of `wallet`'s restricted safe wallet S1) to take
    ///         `wallet` over. Goes to `wallet` for approval.
    function requestMoveForWallet(address wallet) external whenNotPaused returns (uint256 id) {
        (address s1, address s2) = _moveTargets(wallet);
        require(msg.sender == s2, "ACLDAO: only the safe wallet of its safe wallet");
        id = _open(KIND_MOVE_UP, wallet, s2, s1, true);
    }

    // ---------------------------------------------------------------------
    // Safe-wallet proposals: approve / reject / cancel
    // ---------------------------------------------------------------------

    /// @notice Only the proposal's approver approves. Re-checks everything at approval time.
    function approveProposal(uint256 id) external whenNotPaused {
        Proposal memory p = _pendingProposal(id);
        require(msg.sender == _approver(p), p.bySafe ? "ACLDAO: only the wallet approves" : "ACLDAO: only safe wallet approves");
        _checkStillValid(p);

        IATMAccessControl ac = acl();
        _close(id, STATUS_APPROVED, msg.sender);
        if (p.kind == KIND_PROTECTION) ac.daoGrantProtection(p.wallet);
        else ac.daoSetSafeWallet(p.wallet, p.safeWallet);
        emit ProposalApproved(id, p.kind, p.wallet, p.safeWallet);
    }

    /// @notice The approver says no. Works while paused.
    function rejectProposal(uint256 id) external {
        Proposal memory p = _pendingProposal(id);
        require(msg.sender == _approver(p), p.bySafe ? "ACLDAO: only the wallet rejects" : "ACLDAO: only safe wallet rejects");
        _close(id, STATUS_REJECTED, msg.sender);
    }

    /// @notice Whoever asked (or the owner) withdraws. Works while paused.
    function cancelProposal(uint256 id) external {
        Proposal memory p = _pendingProposal(id);
        address requester = p.bySafe ? p.safeWallet : p.wallet;
        require(msg.sender == requester || msg.sender == owner, "ACLDAO: not allowed");
        _close(id, STATUS_CANCELLED, msg.sender);
    }

    /// @notice Who must approve: the wallet if S2 asked, else the safe wallet.
    function approverOf(uint256 id) external view returns (address) {
        return _approver(_proposals[id]);
    }

    // ---------------------------------------------------------------------
    // Safe-wallet proposals: views for the front end
    // ---------------------------------------------------------------------

    function getProposal(uint256 id) external view returns (Proposal memory) {
        require(id != 0 && id <= proposalCount, "ACLDAO: unknown proposal");
        return _proposals[id];
    }

    /// @notice How many proposals are waiting for this approver.
    function pendingProposalCount(address approver) external view returns (uint256) {
        return _pendingIds[approver].length;
    }

    /// @notice How many proposals were ever sent to this approver (any status).
    function proposalCountOf(address approver) external view returns (uint256) {
        return _safeProposalIds[approver].length;
    }

    /// @notice Every proposal waiting for this approver, with details.
    function pendingProposals(address approver)
        external
        view
        returns (uint256[] memory ids, Proposal[] memory items)
    {
        ids = _pendingIds[approver];
        items = new Proposal[](ids.length);
        for (uint256 i; i < ids.length; ++i) items[i] = _proposals[ids[i]];
    }

    /// @notice History of an approver's proposals (oldest first), paginated.
    function proposalsOf(address approver, uint256 offset, uint256 limit)
        external
        view
        returns (uint256[] memory ids, Proposal[] memory items)
    {
        uint256[] storage all = _safeProposalIds[approver];
        uint256 end = offset + limit;
        if (end > all.length) end = all.length;
        uint256 n = end > offset ? end - offset : 0;
        ids = new uint256[](n);
        items = new Proposal[](n);
        for (uint256 i; i < n; ++i) {
            ids[i] = all[offset + i];
            items[i] = _proposals[ids[i]];
        }
    }

    /// @notice Whether the approver could approve this proposal right now, and if not, why
    ///         (the same message approveProposal would revert with).
    function canApprove(uint256 id) external view returns (bool ok, string memory reason) {
        if (paused) return (false, "ACLDAO: paused");
        try this.checkProposal(id) {
            return (true, "");
        } catch Error(string memory r) {
            return (false, r);
        }
    }

    /// @dev Reverts with the reason the proposal can't be approved. Used by canApprove.
    function checkProposal(uint256 id) external view {
        _checkStillValid(_pendingProposal(id));
    }

    // ---------------------------------------------------------------------
    // 2. PROTECTED wallet changes its safe wallet; verifiers approve
    // ---------------------------------------------------------------------

    function proposeSafeWallet(address newSafeWallet) external whenNotPaused {
        require(verifierVoteEnabled, "ACLDAO: verifier vote disabled");
        IATMAccessControl ac = acl();
        address w = msg.sender;
        require(ac.isProtected(w), "ACLDAO: not protected");
        require(!ac.isRestricted(w), "ACLDAO: wallet restricted");
        _checkNewSafeWallet(w, newSafeWallet);

        SafeWalletRequest storage r = safeWalletRequests[w];
        r.newSafeWallet = newSafeWallet;
        r.currentSafeWallet = ac.safeWalletOf(w);
        r.approvals = 0;
        r.threshold = verifierThreshold();
        r.nonce++;
        r.active = true;
        emit SafeWalletProposed(w, newSafeWallet, r.nonce, r.threshold);
    }

    function approveSafeWallet(address protectedWallet, uint256 nonce) external whenNotPaused {
        require(verifierVoteEnabled, "ACLDAO: verifier vote disabled");
        IATMAccessControl ac = acl();
        require(_isVerifier(ac, msg.sender), "ACLDAO: not verifier");
        SafeWalletRequest storage r = safeWalletRequests[protectedWallet];
        require(r.active && r.nonce == nonce, "ACLDAO: no such request");
        require(msg.sender != protectedWallet && msg.sender != r.newSafeWallet, "ACLDAO: verifier is a party");
        require(!_approvals[protectedWallet][nonce][msg.sender], "ACLDAO: already approved");

        _approvals[protectedWallet][nonce][msg.sender] = true;
        uint256 approvals = ++r.approvals;
        emit SafeWalletRequestApproved(protectedWallet, nonce, msg.sender, approvals);

        if (approvals >= r.threshold) {
            require(ac.isProtected(protectedWallet), "ACLDAO: not protected");
            require(!ac.isRestricted(protectedWallet), "ACLDAO: wallet restricted");
            require(ac.safeWalletOf(protectedWallet) == r.currentSafeWallet, "ACLDAO: safe wallet changed");
            r.active = false;
            ac.daoSetSafeWallet(protectedWallet, r.newSafeWallet);
            emit SafeWalletRequestExecuted(protectedWallet, r.newSafeWallet, nonce);
        }
    }

    function cancelSafeWalletRequest(address protectedWallet) external {
        require(msg.sender == protectedWallet || msg.sender == owner, "ACLDAO: not allowed");
        SafeWalletRequest storage r = safeWalletRequests[protectedWallet];
        require(r.active, "ACLDAO: no such request");
        r.active = false;
        emit SafeWalletRequestCancelled(protectedWallet, r.nonce, msg.sender);
    }

    function hasApprovedSafeWallet(address protectedWallet, uint256 nonce, address verifier)
        external
        view
        returns (bool)
    {
        return _approvals[protectedWallet][nonce][verifier];
    }

    // ---------------------------------------------------------------------
    // 3. Custom-type flows (rules per type: setTypeFlow)
    // ---------------------------------------------------------------------

    /// @notice Ask for `wallet` to join (`add`) or leave a custom type. The wallet asks for itself
    ///         (REQUEST_BY_WALLET) or an active verifier asks for it (REQUEST_BY_VERIFIER; its
    ///         request counts as its own vote). Asking again replaces the open request.
    function requestTypeChange(address wallet, uint256 typeId, bool add) external whenNotPaused returns (uint256 id) {
        TypeFlow memory f = _typeFlows[typeId];
        IATMAccessControl ac = acl();
        bool byVerifier = msg.sender != wallet;
        if (byVerifier) {
            require(f.requestBy & REQUEST_BY_VERIFIER != 0, "ACLDAO: verifiers can't ask for this type");
            require(_isVerifier(ac, msg.sender), "ACLDAO: not verifier");
        } else {
            require(f.requestBy & REQUEST_BY_WALLET != 0, "ACLDAO: wallet can't ask for this type");
        }
        _checkTypeChange(ac, f, wallet, typeId, add);

        address approver;
        if (f.approveBy == APPROVE_BY_SAFE_WALLET) {
            approver = _usableSafeWallet(ac, wallet);
            require(approver != msg.sender, "ACLDAO: requester is the approver");
        }

        uint256 old = openTypeRequestOf[wallet][typeId];
        if (old != 0) _closeTypeRequest(old, STATUS_CANCELLED);

        id = ++typeRequestCount;
        TypeRequest storage r = _typeRequests[id];
        r.wallet = wallet;
        r.typeId = typeId;
        r.add = add;
        r.status = STATUS_PENDING;
        r.approveBy = f.approveBy;
        r.threshold = f.approveBy == APPROVE_BY_VERIFIERS ? f.threshold : 1;
        r.createdAt = uint64(block.timestamp);
        r.requester = msg.sender;
        r.approver = approver;
        openTypeRequestOf[wallet][typeId] = id;
        emit TypeRequestCreated(id, wallet, typeId, add, msg.sender, approver, r.threshold);

        if (byVerifier && f.approveBy == APPROVE_BY_VERIFIERS) _approveType(ac, id, r);
    }

    /// @notice Verifier mode: an active verifier (not the wallet) votes; executes at the threshold.
    ///         Safe-wallet mode: only the safe wallet recorded at request time approves.
    function approveTypeRequest(uint256 id) external whenNotPaused {
        TypeRequest storage r = _pendingTypeRequest(id);
        IATMAccessControl ac = acl();
        if (r.approveBy == APPROVE_BY_SAFE_WALLET) {
            require(msg.sender == r.approver, "ACLDAO: only safe wallet approves");
        } else {
            require(_isVerifier(ac, msg.sender), "ACLDAO: not verifier");
        }
        _approveType(ac, id, r);
    }

    /// @notice The safe wallet (safe-wallet mode) says no. Works while paused.
    function rejectTypeRequest(uint256 id) external {
        TypeRequest storage r = _pendingTypeRequest(id);
        require(r.approveBy == APPROVE_BY_SAFE_WALLET && msg.sender == r.approver, "ACLDAO: only safe wallet rejects");
        _closeTypeRequest(id, STATUS_REJECTED);
    }

    /// @notice The requester, the wallet itself or the owner withdraws. Works while paused.
    function cancelTypeRequest(uint256 id) external {
        TypeRequest storage r = _pendingTypeRequest(id);
        require(msg.sender == r.requester || msg.sender == r.wallet || msg.sender == owner, "ACLDAO: not allowed");
        _closeTypeRequest(id, STATUS_CANCELLED);
    }

    function typeFlowOf(uint256 typeId) external view returns (TypeFlow memory) {
        return _typeFlows[typeId];
    }

    function getTypeRequest(uint256 id) external view returns (TypeRequest memory) {
        require(id != 0 && id <= typeRequestCount, "ACLDAO: unknown request");
        return _typeRequests[id];
    }

    function hasApprovedTypeRequest(uint256 id, address verifier) external view returns (bool) {
        return _typeApprovals[id][verifier];
    }

    // ---------------------------------------------------------------------
    // Internal
    // ---------------------------------------------------------------------

    /// @dev Counts one vote; at the threshold re-checks the flow and the wallet, then calls the ACL.
    function _approveType(IATMAccessControl ac, uint256 id, TypeRequest storage r) internal {
        require(msg.sender != r.wallet, "ACLDAO: wallet can't approve");
        require(!_typeApprovals[id][msg.sender], "ACLDAO: already approved");
        _typeApprovals[id][msg.sender] = true;
        uint16 approvals = ++r.approvals;
        emit TypeRequestApproved(id, msg.sender, approvals);
        if (approvals < r.threshold) return;

        _checkTypeChange(ac, _typeFlows[r.typeId], r.wallet, r.typeId, r.add);
        if (r.approveBy == APPROVE_BY_SAFE_WALLET) {
            require(_usableSafeWallet(ac, r.wallet) == r.approver, "ACLDAO: safe wallet changed");
        }
        _closeTypeRequest(id, STATUS_APPROVED);
        ac.daoSetType(r.wallet, r.typeId, r.add);
        emit TypeRequestExecuted(id, r.wallet, r.typeId, r.add);
    }

    /// @dev The flow allows it now, the ACL opened the type, and the wallet is in the other state.
    ///      Joining also needs a wallet that is not frozen / blacklisted.
    function _checkTypeChange(IATMAccessControl ac, TypeFlow memory f, address wallet, uint256 typeId, bool add)
        internal
        view
    {
        require(wallet != address(0), "ACLDAO: zero address");
        require(f.requestBy != 0 && (add ? f.allowAdd : f.allowRemove), "ACLDAO: type flow off");
        (,,,, bool daoAllowed) = ac.typeInfo(typeId);
        require(daoAllowed, "ACLDAO: type not open to the dao");
        if (add) {
            require(!ac.hasType(wallet, typeId), "ACLDAO: already has type");
            require(!ac.isRestricted(wallet), "ACLDAO: wallet restricted");
        } else {
            require(ac.hasType(wallet, typeId), "ACLDAO: does not have type");
        }
    }

    /// @notice Holds the verifier type and is not frozen / blacklisted.
    function isVerifier(address account) external view returns (bool) {
        return _isVerifier(acl(), account);
    }

    function _isVerifier(IATMAccessControl ac, address a) internal view returns (bool) {
        uint256 t = verifierTypeId;
        return t != 0 && ac.hasType(a, t) && !ac.isRestricted(a);
    }

    function _requireCustomType(uint256 typeId) internal view {
        (, bool exists,,,) = acl().typeInfo(typeId);
        require(typeId >= FIRST_CUSTOM_TYPE && exists, "ACLDAO: not a custom type");
    }

    function _usableSafeWallet(IATMAccessControl ac, address wallet) internal view returns (address safe) {
        safe = ac.safeWalletOf(wallet);
        require(safe != address(0), "ACLDAO: no safe wallet");
        require(!ac.isRestricted(safe) && !ac.isSafeWalletRevoked(safe), "ACLDAO: safe wallet restricted");
    }

    function _pendingTypeRequest(uint256 id) internal view returns (TypeRequest storage r) {
        r = _typeRequests[id];
        require(r.status == STATUS_PENDING, "ACLDAO: request not pending");
    }

    function _closeTypeRequest(uint256 id, uint8 status) internal {
        TypeRequest storage r = _typeRequests[id];
        r.status = status;
        delete openTypeRequestOf[r.wallet][r.typeId];
        emit TypeRequestClosed(id, status, msg.sender);
    }

    function _open(uint8 kind, address wallet, address safe, address fromSafe, bool bySafe) internal returns (uint256 id) {
        uint256 old = openProposalOf[wallet][kind];
        if (old != 0) _close(old, STATUS_CANCELLED, msg.sender); // asking again replaces the old one

        id = ++proposalCount;
        Proposal memory p = Proposal({
            wallet: wallet,
            kind: kind,
            status: STATUS_PENDING,
            createdAt: uint64(block.timestamp),
            bySafe: bySafe,
            safeWallet: safe,
            fromSafe: fromSafe
        });
        _proposals[id] = p;
        openProposalOf[wallet][kind] = id;
        address approver = _approver(p);
        _safeProposalIds[approver].push(id);
        _pendingIds[approver].push(id);
        _pendingPos[id] = _pendingIds[approver].length;
        emit ProposalCreated(id, kind, wallet, safe, fromSafe);
    }

    function _approver(Proposal memory p) internal pure returns (address) {
        return p.bySafe ? p.wallet : p.safeWallet;
    }

    function _close(uint256 id, uint8 status, address by) internal {
        Proposal storage p = _proposals[id];
        p.status = status;
        delete openProposalOf[p.wallet][p.kind];

        uint256[] storage list = _pendingIds[_approver(p)];
        uint256 i = _pendingPos[id] - 1;
        uint256 last = list[list.length - 1];
        list[i] = last;
        _pendingPos[last] = i + 1;
        list.pop();
        delete _pendingPos[id];
        emit ProposalClosed(id, status, by);
    }

    function _pendingProposal(uint256 id) internal view returns (Proposal memory p) {
        p = _proposals[id];
        require(p.status == STATUS_PENDING, "ACLDAO: proposal not pending");
    }

    /// @dev The links seen at request time must still hold and the ACL rules must still pass.
    function _checkStillValid(Proposal memory p) internal view {
        if (p.kind == KIND_PROTECTION) {
            require(_checkProtectable(p.wallet) == p.safeWallet, "ACLDAO: safe wallet changed");
        } else {
            (address s1, address s2) = _moveTargets(p.wallet);
            require(s1 == p.fromSafe && s2 == p.safeWallet, "ACLDAO: links changed");
            IATMAccessControl ac = acl();
            require(!ac.isRestricted(s2) && !ac.isSafeWalletRevoked(s2), "ACLDAO: safe wallet restricted");
            require(!ac.isProtected(s2), "ACLDAO: safe wallet is protected");
        }
    }

    function _checkProtectable(address frozenWallet) internal view returns (address safe) {
        IATMAccessControl ac = acl();
        require(
            ac.isFrozen(frozenWallet) && !ac.isProtected(frozenWallet) && !ac.isBlacklisted(frozenWallet),
            "ACLDAO: not frozen"
        );
        require(ac.activeSafeWalletCount(frozenWallet) == 0, "ACLDAO: wallet is a safe wallet");
        safe = ac.safeWalletOf(frozenWallet);
        require(safe != address(0), "ACLDAO: no safe wallet");
        require(!ac.isRestricted(safe) && !ac.isSafeWalletRevoked(safe), "ACLDAO: safe wallet restricted");
        require(!ac.isProtected(safe), "ACLDAO: safe wallet is protected");
    }

    function _checkNewSafeWallet(address w, address newSafeWallet) internal view {
        IATMAccessControl ac = acl();
        require(newSafeWallet != address(0), "ACLDAO: zero safe wallet");
        require(newSafeWallet != w, "ACLDAO: safe wallet cannot be self");
        require(newSafeWallet != ac.safeWalletOf(w), "ACLDAO: already safe wallet");
        require(
            !ac.isRestricted(newSafeWallet) && !ac.isSafeWalletRevoked(newSafeWallet),
            "ACLDAO: safe wallet is itself restricted"
        );
        require(!ac.isProtected(newSafeWallet), "ACLDAO: safe wallet is protected");
    }

    /// @dev W is FROZEN (not blacklisted) or PROTECTED, its safe wallet S1 is restricted, and S1
    ///      has its own safe wallet S2.
    function _moveTargets(address p) internal view returns (address s1, address s2) {
        IATMAccessControl ac = acl();
        require(ac.isProtected(p) || (ac.isFrozen(p) && !ac.isBlacklisted(p)), "ACLDAO: not frozen or protected");
        s1 = ac.safeWalletOf(p);
        require(s1 != address(0), "ACLDAO: no safe wallet");
        require(ac.isRestricted(s1) || ac.isSafeWalletRevoked(s1), "ACLDAO: safe wallet not restricted");
        s2 = ac.safeWalletOf(s1);
        require(s2 != address(0), "ACLDAO: safe wallet has no safe wallet");
    }

    function version() external pure returns (string memory) {
        return "v1.0.0";
    }
}

