// SPDX-License-Identifier: MIT
pragma solidity ^0.8.0;

/// @title IATMAccessControl
/// @notice Shared interface of ATMAccessControl for callers (Factory, ATMAccessControlDAO, others).
interface IATMAccessControl {
    // --- status (used by live contracts) ---
    function isBlacklisted(address account) external view returns (bool);
    function isFrozen(address account) external view returns (bool);
    function isRestricted(address account) external view returns (bool);
    function redirectTarget(address account) external view returns (address);
    function safeWalletOf(address account) external view returns (address);
    function isSafeWalletRevoked(address account) external view returns (bool);
    function activeSafeWalletCount(address account) external view returns (uint256);
    function operators(address account) external view returns (bool);
    function owner() external view returns (address);

    // --- types / rules ---
    function isProtected(address account) external view returns (bool);
    function isAllowed(address account, bytes32 action) external view returns (bool);
    function isAllowedToken(address account, bytes32 action, address token) external view returns (bool);

    // --- connections (Factory) ---
    function canCreateConnection(
        address creator,
        address userB,
        address token,
        uint256 totalPlan,
        uint256 percentA,
        uint256 lockDays
    ) external view returns (bool allowed, uint8 reason);

    function checkConnection(
        address creator,
        address userB,
        address token,
        uint256 totalPlan,
        uint256 percentA,
        uint256 lockDays
    ) external view returns (bool allowed, uint8 reason);

    // --- hooks for the ACL DAO ---
    function daoGrantProtection(address wallet) external;
    function daoSetSafeWallet(address wallet, address newSafeWallet) external;
    /// @dev custom types the owner opened with setTypeDaoAllowed; per-type flows live in the DAO
    function daoSetType(address account, uint256 typeId, bool add) external;
    function hasType(address account, uint256 typeId) external view returns (bool);
    function typeInfo(uint256 typeId)
        external
        view
        returns (string memory name, bool exists, bool disabled, bool defaultBlocked, bool daoAllowed);
}
